//! IR → Swift source text. Rendering is fully deterministic: ID newtypes in
//! `ID_TYPES` order first, then string enums, then structs, each in bundle
//! first-occurrence order.

use super::model::{StructDef, SwiftModel, SwiftType, TaggedEnum};
use super::overrides;
use std::fmt::Write;

const HEADER: &str = "\
// Generated by generate-protocol-artifacts — do not edit.
// Regenerate: cargo run --manifest-path backend/Cargo.toml -p ottam-protocol --bin generate-protocol-artifacts

import Foundation
";

pub fn render(model: &SwiftModel) -> String {
    let mut out = String::new();
    out.push_str(HEADER);

    out.push_str("\n// MARK: - Wire IDs\n");
    for id_type in overrides::ID_TYPES {
        write_id_newtype(&mut out, id_type);
    }

    out.push_str("\n// MARK: - Wire enums\n");
    for string_enum in &model.string_enums {
        write!(
            out,
            "\npublic enum {}: String, Codable, Equatable, Sendable {{\n",
            string_enum.name
        )
        .unwrap();
        for case in &string_enum.cases {
            if let Some(doc) = &case.doc {
                for line in doc.lines() {
                    writeln!(out, "    /// {line}").unwrap();
                }
            }
            writeln!(out, "    case {}", escape_identifier(&case.name)).unwrap();
        }
        out.push_str("}\n");
    }

    out.push_str("\n// MARK: - Wire structs\n");
    for struct_def in &model.structs {
        write_struct(&mut out, struct_def);
    }

    out.push_str("\n// MARK: - Wire unions (internally tagged)\n");
    for tagged in &model.tagged_enums {
        write_tagged_enum(&mut out, tagged);
    }

    out
}

/// Internally-tagged enum: cases with labeled associated values, a private
/// CodingKeys covering the tag plus every payload key, a private `Kind` tag
/// enum, and hand-rolled `init(from:)`/`encode(to:)` switching on the tag.
fn write_tagged_enum(out: &mut String, tagged: &TaggedEnum) {
    let name = &tagged.name;
    writeln!(out, "\npublic enum {name}: Codable, Equatable, Sendable {{").unwrap();
    for variant in &tagged.variants {
        let case_name = escape_identifier(&variant.tag_value);
        if variant.fields.is_empty() {
            writeln!(out, "    case {case_name}").unwrap();
        } else {
            let payload: Vec<String> = variant
                .fields
                .iter()
                .map(|field| format!("{}: {}", escape_identifier(&field.name), field.ty.render()))
                .collect();
            writeln!(out, "    case {case_name}({})", payload.join(", ")).unwrap();
        }
    }

    // Tag key first, then payload keys in first-appearance order.
    let mut coding_keys = vec![tagged.tag.clone()];
    for variant in &tagged.variants {
        for field in &variant.fields {
            if !coding_keys.contains(&field.wire_name) {
                coding_keys.push(field.wire_name.clone());
            }
        }
    }
    let keys: Vec<String> = coding_keys
        .iter()
        .map(|key| escape_identifier(key))
        .collect();
    out.push('\n');
    write_case_list(out, "private enum CodingKeys: String, CodingKey", &keys);
    let kinds: Vec<String> = tagged
        .variants
        .iter()
        .map(|variant| escape_identifier(&variant.tag_value))
        .collect();
    write_case_list(out, "private enum Kind: String, Codable", &kinds);

    let tag_key = escape_identifier(&tagged.tag);
    out.push_str("\n    public init(from decoder: Decoder) throws {\n");
    out.push_str("        let container = try decoder.container(keyedBy: CodingKeys.self)\n");
    writeln!(
        out,
        "        switch try container.decode(Kind.self, forKey: .{tag_key}) {{"
    )
    .unwrap();
    for variant in &tagged.variants {
        let case_name = escape_identifier(&variant.tag_value);
        writeln!(out, "        case .{case_name}:").unwrap();
        if variant.fields.is_empty() {
            writeln!(out, "            self = .{case_name}").unwrap();
            continue;
        }
        let decodes: Vec<String> = variant
            .fields
            .iter()
            .map(|field| {
                let key = escape_identifier(&field.name);
                // An argument label takes a keyword as is; escaping it warns.
                let label = &field.name;
                if let Some(default) = &field.decode_default {
                    return format!(
                        "{label}: try container.decodeIfPresent({}.self, forKey: .{key}) ?? {default}",
                        field.ty.render()
                    );
                }
                match &field.ty {
                    SwiftType::Optional(inner) => format!(
                        "{label}: try container.decodeIfPresent({}.self, forKey: .{key})",
                        inner.render()
                    ),
                    ty => format!(
                        "{label}: try container.decode({}.self, forKey: .{key})",
                        ty.render()
                    ),
                }
            })
            .collect();
        let single_line = format!("            self = .{case_name}({})", decodes.join(", "));
        if single_line.len() <= 100 {
            writeln!(out, "{single_line}").unwrap();
        } else {
            writeln!(out, "            self = .{case_name}(").unwrap();
            for (index, decode) in decodes.iter().enumerate() {
                let comma = if index + 1 < decodes.len() { "," } else { "" };
                writeln!(out, "                {decode}{comma}").unwrap();
            }
            out.push_str("            )\n");
        }
    }
    out.push_str("        }\n    }\n");

    out.push_str("\n    public func encode(to encoder: Encoder) throws {\n");
    out.push_str("        var container = encoder.container(keyedBy: CodingKeys.self)\n");
    out.push_str("        switch self {\n");
    for variant in &tagged.variants {
        let case_name = escape_identifier(&variant.tag_value);
        if variant.fields.is_empty() {
            writeln!(out, "        case .{case_name}:").unwrap();
        } else {
            let bindings: Vec<String> = variant
                .fields
                .iter()
                .map(|field| format!("let {}", escape_identifier(&field.name)))
                .collect();
            writeln!(out, "        case .{case_name}({}):", bindings.join(", ")).unwrap();
        }
        writeln!(
            out,
            "            try container.encode(Kind.{case_name}, forKey: .{tag_key})"
        )
        .unwrap();
        for field in &variant.fields {
            let key = escape_identifier(&field.name);
            let method = if field.ty.is_optional() {
                "encodeIfPresent"
            } else {
                "encode"
            };
            writeln!(
                out,
                "            try container.{method}({key}, forKey: .{key})"
            )
            .unwrap();
        }
    }
    out.push_str("        }\n    }\n}\n");
}

/// `header { case a, b, c }` on one line when it fits in 100 columns, else a
/// block with case lines greedily wrapped.
fn write_case_list(out: &mut String, header: &str, names: &[String]) {
    let joined = names.join(", ");
    let single_line = format!("    {header} {{ case {joined} }}");
    if single_line.len() <= 100 {
        writeln!(out, "{single_line}").unwrap();
        return;
    }
    writeln!(out, "    {header} {{").unwrap();
    let mut line = String::new();
    for name in names {
        let candidate = if line.is_empty() {
            format!("        case {name}")
        } else {
            format!("{line}, {name}")
        };
        if candidate.len() > 100 && !line.is_empty() {
            writeln!(out, "{line}").unwrap();
            line = format!("        case {name}");
        } else {
            line = candidate;
        }
    }
    writeln!(out, "{line}").unwrap();
    out.push_str("    }\n");
}

fn write_struct(out: &mut String, struct_def: &StructDef) {
    let name = &struct_def.name;
    out.push('\n');
    write_doc_comment(out, name, "", "");
    let mut conformances = vec!["Codable", "Equatable", "Sendable"];
    if let Some((_, extra)) = overrides::EXTRA_CONFORMANCES
        .iter()
        .find(|(ty, _)| ty == name)
    {
        conformances.extend_from_slice(extra);
    }
    writeln!(out, "public struct {name}: {} {{", conformances.join(", ")).unwrap();
    for field in &struct_def.fields {
        write_doc_comment(out, name, &field.name, "    ");
        if let Some(doc) = &field.doc {
            for line in doc.lines() {
                writeln!(out, "    /// {line}").unwrap();
            }
        }
        writeln!(
            out,
            "    public var {}: {}",
            escape_identifier(&field.name),
            field.ty.render()
        )
        .unwrap();
    }

    {
        if struct_def.fields.is_empty() {
            out.push_str("\n    public init() {}\n");
        } else {
            let parameters: Vec<String> = struct_def
                .fields
                .iter()
                .map(|field| {
                    let suffix = match overrides::init_param_default(name, &field.name) {
                        Some(default) => format!(" = {default}"),
                        None if field.ty.is_optional() => " = nil".to_string(),
                        None => String::new(),
                    };
                    format!(
                        "{}: {}{suffix}",
                        escape_identifier(&field.name),
                        field.ty.render()
                    )
                })
                .collect();
            let single_line = format!("\n    public init({}) {{\n", parameters.join(", "));
            if single_line.lines().last().unwrap_or_default().len() <= 100 {
                out.push_str(&single_line);
            } else {
                out.push_str("\n    public init(\n");
                for (index, parameter) in parameters.iter().enumerate() {
                    let comma = if index + 1 < parameters.len() {
                        ","
                    } else {
                        ""
                    };
                    writeln!(out, "        {parameter}{comma}").unwrap();
                }
                out.push_str("    ) {\n");
            }
            for field in &struct_def.fields {
                let escaped = escape_identifier(&field.name);
                writeln!(out, "        self.{escaped} = {escaped}").unwrap();
            }
            out.push_str("    }\n");
        }
    }

    if overrides::has_property_rename(name)
        || struct_def
            .fields
            .iter()
            .any(|field| field.decode_default.is_some())
    {
        write_custom_decoder(out, struct_def);
    }
    out.push_str("}\n");
}

/// Emits explicit CodingKeys + `init(from:)` for tolerant-default types.
/// `encode(to:)` stays synthesized (from the same CodingKeys), matching the
/// hand-written originals.
fn write_custom_decoder(out: &mut String, struct_def: &StructDef) {
    let name = &struct_def.name;
    out.push_str("\n    private enum CodingKeys: String, CodingKey {\n");
    for field in &struct_def.fields {
        if field.name == field.wire_name {
            writeln!(out, "        case {}", escape_identifier(&field.name)).unwrap();
        } else {
            writeln!(
                out,
                "        case {} = \"{}\"",
                escape_identifier(&field.name),
                field.wire_name
            )
            .unwrap();
        }
    }
    out.push_str("    }\n");

    out.push_str("\n    public init(from decoder: Decoder) throws {\n");
    out.push_str("        let container = try decoder.container(keyedBy: CodingKeys.self)\n");
    for field in &struct_def.fields {
        let escaped = escape_identifier(&field.name);
        let key = format!(".{escaped}");
        if let Some(default) = &field.decode_default {
            if let Some(comment) = overrides::decode_default_comment(name, &field.wire_name) {
                writeln!(out, "        // {comment}").unwrap();
            }
            writeln!(
                out,
                "        {escaped} = try container.decodeIfPresent({}.self, forKey: {key}) ?? {default}",
                field.ty.render()
            )
            .unwrap();
        } else if let SwiftType::Optional(inner) = &field.ty {
            writeln!(
                out,
                "        {escaped} = try container.decodeIfPresent({}.self, forKey: {key})",
                inner.render()
            )
            .unwrap();
        } else {
            writeln!(
                out,
                "        {escaped} = try container.decode({}.self, forKey: {key})",
                field.ty.render()
            )
            .unwrap();
        }
    }
    out.push_str("    }\n");
}

fn write_doc_comment(out: &mut String, type_name: &str, field: &str, indent: &str) {
    if let Some((_, _, lines)) = overrides::DOC_COMMENTS
        .iter()
        .find(|(ty, fld, _)| *ty == type_name && *fld == field)
    {
        for line in *lines {
            writeln!(out, "{indent}/// {line}").unwrap();
        }
    }
}

fn write_id_newtype(out: &mut String, name: &str) {
    write!(
        out,
        "\npublic struct {name}: Codable, Hashable, Sendable {{
    public var rawValue: String

    public init(_ rawValue: String) {{
        self.rawValue = rawValue
    }}

    public init(from decoder: Decoder) throws {{
        rawValue = try decoder.singleValueContainer().decode(String.self)
    }}

    public func encode(to encoder: Encoder) throws {{
        var container = encoder.singleValueContainer()
        try container.encode(rawValue)
    }}
}}\n"
    )
    .unwrap();
}

/// Backtick-escape Swift keywords so a wire value like `default` stays legal.
fn escape_identifier(identifier: &str) -> String {
    const KEYWORDS: &[&str] = &[
        "associatedtype",
        "class",
        "deinit",
        "enum",
        "extension",
        "func",
        "import",
        "init",
        "inout",
        "internal",
        "let",
        "operator",
        "private",
        "protocol",
        "public",
        "static",
        "struct",
        "subscript",
        "typealias",
        "var",
        "break",
        "case",
        "continue",
        "default",
        "defer",
        "do",
        "else",
        "fallthrough",
        "for",
        "guard",
        "if",
        "in",
        "repeat",
        "return",
        "switch",
        "where",
        "while",
        "as",
        "catch",
        "false",
        "is",
        "nil",
        "rethrows",
        "self",
        "Self",
        "super",
        "throw",
        "throws",
        "true",
        "try",
    ];
    if KEYWORDS.contains(&identifier) {
        format!("`{identifier}`")
    } else {
        identifier.to_string()
    }
}
